<script lang="ts">
 import ArticleThumb from './learning/ArticleThumb.svelte';
 import ArticleBody from './learning/ArticleBody.svelte';import {fly}from'svelte/transition';import{cubicOut}from'svelte/easing';import{prefersReducedMotion}from'svelte/motion';import{tick}from'svelte';
 import {t} from '#lib/i18n.ts';
 import {onMount,onDestroy} from 'svelte';import {page} from '$app/state';import Icon from './Icon.svelte';import WineBottle from './WineBottle.svelte';import Modal from './Modal.svelte';import NotesForm from './NotesForm.svelte';import {api,refreshSession,session} from '#lib/client.svelte.ts';import {steps}from'#lib/content.ts';import{getWines,getArticle as articleBySlug,imageSrc,creditFor,loadEditorial}from'#lib/editorial.svelte.ts';const wines=$derived(getWines());import QRCode from 'qrcode';
 let {code,hostMode=false}:{code:string;hostMode?:boolean}=$props();
 let room=$state<any>(null);let member=$state<any>(null);let isHost=$state(false);let loading=$state(true);let error=$state('');let name=$state('');let busy=$state(false);let index=$state(0);let following=$state(true);let connected=$state(false);let stream:EventSource|undefined;let disposed=false;let selection=$state<HTMLDivElement>();let direction=$state(1);let qrOpen=$state(false);let settingsOpen=$state(false);let membersOpen=$state(false);let qr=$state('');let joinUrl=$state('');let copied=$state(false);let members=$state<any[]>([]);let finishOpen=$state(false);let settingsBusy=$state(false);
 const defaults=()=>({redName:'',redProducer:'',redRegion:'',redGrape:'',redStory:'',redRegionText:'',redProducerText:'',redGrapeText:'',redSource:'',rieslingLabel:'',vintages:['','','','']});let settings=$state(defaults());
 const step=$derived(steps[index]);const article=$derived(step?.slug?articleBySlug(step.slug):undefined);const wine=$derived(wines[step?.wine??0]);const currentName=$derived(step?.wine===3&&room?.settings.redName?room.settings.redName:step?.wine===2&&room?.settings.rieslingLabel?room.settings.rieslingLabel:wine.name);
 const wineSteps=$derived(steps.map((s,i)=>({...s,index:i})).filter(s=>s.wine===step.wine&&s.type!=='break'&&s.type!=='finish'));
 function scrollTop(){window.scrollTo({top:0,behavior:'instant'});tick().then(()=>{selection?.querySelector('button.active')?.scrollIntoView({block:'nearest',inline:'nearest',behavior:prefersReducedMotion.current?'instant':'smooth'});});}
 async function load(){loading=true;error='';try{const d=await api('rooms/'+code);room=d.room;member=d.member;isHost=d.isHost;index=room.step;if(hostMode&&!isHost){error='Melde dich mit dem Host-Konto an, um dieses Tasting zu steuern.';}else if(member){const selected=page.url.searchParams.get('wine');if(selected){const n=steps.findIndex(s=>wines[s.wine].id===selected&&s.type==='notes');if(n>=0){index=n;following=false;}}connect();}settings={...defaults(),...room.settings};}catch(e){error=(e as Error).message;}loading=false;}
 function connect(){if(disposed)return;stream?.close();stream=new EventSource('/api/rooms/'+code+'/stream');stream.onopen=()=>connected=true;stream.onerror=()=>connected=false;stream.addEventListener('tasting',async(event)=>{const e=JSON.parse((event as MessageEvent).data);if(e.type==='ParticipantJoined'&&hostMode){await loadMembers();return;}if(e.type==='ContentPublished'){await loadEditorial(hostMode&&isHost);return;}const p=e.payload;if(p.version!==undefined&&p.version>=room.version){room={...room,...p};if(following||hostMode){const changed=index!==room.step;index=room.step;if(changed)scrollTop();}}});}
 async function join(){busy=true;error='';try{await api('rooms/'+code+'/join',{name});member={name};await refreshSession();connect();}catch(e){error=(e as Error).message;}busy=false;}
 async function move(target:number){if(target<0||target>=steps.length)return;direction=target>=index?1:-1;error='';if(hostMode){if(busy)return;busy=true;try{const d=await api('rooms/'+code+'/advance',{step:target,version:room.version,requestId:crypto.randomUUID()});room=d.room;index=room.step;scrollTop();}catch(e){error=(e as Error).message;try{const d=await api('rooms/'+code);room=d.room;index=room.step;}catch{}}busy=false;}else{following=false;index=target;scrollTop();}}
 function follow(){following=true;index=room.step;scrollTop();}
 function notes(w:number){move(steps.findIndex(s=>s.wine===w&&s.type==='notes'));}
 async function showQR(){qrOpen=true;joinUrl=location.origin+'/tasting/'+code;if(!qr)qr=await QRCode.toDataURL(joinUrl,{width:500,margin:2,color:{dark:'#293e30',light:'#ffffff'},errorCorrectionLevel:'M'});}
 async function copy(){try{await navigator.clipboard.writeText(joinUrl);copied=true;setTimeout(()=>copied=false,2000);}catch{error='Kopiere den Link bitte direkt aus dem Feld.';}}
 async function loadMembers(){try{const d=await api('rooms/'+code+'/members');members=d.members;}catch{}}
 async function saveSettings(){settingsBusy=true;error='';try{const d=await api('rooms/'+code+'/settings',settings);room=d.room;settingsOpen=false;}catch(e){error=(e as Error).message;}settingsBusy=false;}
 async function finish(){busy=true;try{const d=await api('rooms/'+code+'/advance',{step:steps.length-1,version:room.version,requestId:crypto.randomUUID(),closed:true});room=d.room;index=room.step;finishOpen=false;}catch(e){error=(e as Error).message;}busy=false;}
 function downloadHost(){const text='# '+room.name+'\n\n'+steps.filter(s=>s.type==='story'||s.type==='break').map(s=>{const a=articleBySlug(s.slug!);return a?'## '+wines[s.wine].name+' · '+a.title+'\n\n'+[a.intro,...a.paragraphs,...(a.sections||[]).flatMap(s=>[s.title,s.body]),...a.host,'Gut zu wissen: '+a.fact,...a.sources.map(s=>s.label+': '+s.url)].join('\n\n'):'';}).join('\n\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));a.download='sip-happens-hostwissen.md';a.click();URL.revokeObjectURL(a.href);}
 onMount(async()=>{await load();if(hostMode&&isHost)loadMembers();});onDestroy(()=>{disposed=true;stream?.close();});
</script>
<svelte:head><title>{hostMode?'Host · ':''}{room?.name||'Tasting'} {t('m_46c3600dd1')}</title></svelte:head>
{#if loading}<div class="loading-state"><Icon name="loader"/>{t('m_eacaebc8c0')}</div>{:else if !room||hostMode&&!isHost}<div class="join-page"><div class="join-card"><span class="teaser-icon peach"><Icon name="help" size={27}/></span><h1>{hostMode?'Als Host anmelden':'Tasting nicht gefunden.'}</h1><p>{error}</p><a href={hostMode?'/konto?next=/host/'+code:'/'} class="button primary">{hostMode?'Zum Host-Login':'Zur Übersicht'}<Icon name="right" size={17}/></a></div></div>
{:else if !member}<div class="join-page"><div class="join-card"><span class="teaser-icon mint"><Icon name="wine" size={29}/></span><span class="eyebrow">{t('m_fda56c212c')}</span><h1 style="margin-top:13px">{room.name}</h1><p>{t('m_291f27ec25')}</p>{#if room.closed}<p class="error">{t('m_38eab65927')}</p><a href="/entdecken" class="button primary">{t('m_ce3e9a951a')}</a>{:else}<form onsubmit={(e)=>{e.preventDefault();join();}}><label>{t('m_1dd84fdadd')}<input bind:value={name} required maxlength="40" placeholder={t('m_8f59091243')} autocomplete="given-name"/></label>{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="button primary full" disabled={busy}>{busy?'Du kommst dazu …':'Ich bin dabei'}<Icon name="right" size={18}/></button></form><small>{t('m_e7114fda11')}</small>{/if}</div></div>
{:else}<div class="tasting-page"><div class="tasting-titlebar"><div><a href="/" class="icon-button" aria-label={t('m_90d08e27d5')}><Icon name="left" size={17}/></a><h1>{room.name}</h1><span class="live-badge" class:offline={!connected}><Icon name="live" size={13}/>{room.closed?'Beendet':connected?'LIVE':'Verbinde …'}</span></div><span class="step-counter">{hostMode?'Host-Ansicht':'Hallo, '+member.name}</span></div>
{#if hostMode}<div class="host-console"><div><Icon name="sound" size={19}/><span><strong>{t('m_c08a4ced3f')}</strong><small>{members.length?members.filter(m=>m.name!=='Host').length:0} {t('m_a707974daf')} {code}</small></span></div><div><button class="text-button" onclick={showQR}><Icon name="qr" size={17}/>{t('m_09f0221689')}</button><button class="icon-button" aria-label={t('m_588ce58587')} onclick={()=>{membersOpen=true;loadMembers();}}><Icon name="users" size={18}/></button><button class="icon-button" aria-label={t('m_4bbab48042')} onclick={()=>{settings={...defaults(),...room.settings};settingsOpen=true;}}><Icon name="settings" size={18}/></button><button class="icon-button" aria-label={t('m_692b78f2cc')} onclick={downloadHost}><Icon name="download" size={18}/></button></div></div>{:else if !following}<div class="recent-session" style="margin-bottom:18px"><div><Icon name="pause" size={16}/><span>{t('m_aa5f4b4abf')}</span></div><button class="text-button" onclick={follow}>{t('m_50f3cc0401')}<Icon name="live" size={16}/></button></div>{/if}
{#if error}<p class="error" role="alert" style="margin-bottom:18px">{error}</p>{/if}
<div bind:this={selection} class="selection-list" aria-label={t('m_37f2cc84e9')}>{#each wines as w,i}<button class:active={step.wine===i&&step.type!=='finish'} onclick={()=>move(steps.findIndex(s=>s.wine===i&&s.type!=='break'))}><span class="number">0{i+1}</span>{i===3&&room.settings.redName?room.settings.redName:w.name}</button>{/each}</div>
{#if !hostMode&&following&&step.type!=='finish'}<div class="mobile-follow-status"><Icon name="live" size={14}/><strong>{t('tasting.following')}</strong><span>{t('tasting.free')}</span></div>{/if}
<div class="tasting-workspace"><div>{#key index}<div class="story-transition" in:fly={{y:prefersReducedMotion.current?0:8*direction,duration:prefersReducedMotion.current?0:190,easing:cubicOut}}>
{#if step.type==='finish'}<section class="story-card finish-card"><span class="teaser-icon mint"><Icon name="heart" size={27}/></span><span class="eyebrow">{t('m_3c6d4fb773')}</span><h2>{t('m_fc7af2078e')}</h2><p>{t('m_9332d99fcb')}</p>{#if session.user}<a href="/notizen" class="button primary">{t('m_b2ba0c20a4')}<Icon name="right" size={17}/></a>{:else}<p>{t('m_9ac7f14fa4')}</p><a href="/konto" class="button primary">{t('m_9f791f3dea')}<Icon name="right" size={17}/></a>{/if}<div class="finish-links"><a href="/notizen" class="text-button">{t('m_f2bd5848b0')}<Icon name="notes" size={16}/></a><a href="/entdecken" class="text-button">{t('m_4d384e7a0f')}<Icon name="compass" size={16}/></a></div>{#if hostMode&&!room.closed}<button class="button outline" onclick={()=>finishOpen=true} style="margin-top:30px">{t('m_3e896fe75c')}</button>{/if}</section>
{:else if step.type==='notes'}<section class="story-card"><div class="story-content"><div class="eyebrow">{t('m_e2a842ce71')}{step.wine+1} {t('m_8c53026091')}</div><h2>{t('m_00936e201e')}</h2><div class="notes-wine-heading"><WineBottle {wine} interactive/><div><h3>{currentName}</h3><p>{step.wine===3&&room.settings.redProducer?room.settings.redProducer:wine.producer}</p><span class="wine-style">{wine.style}</span></div></div>{#key wine.id}<NotesForm room={code} wine={wine.id} hint={wine.hint} onEdit={()=>{if(!hostMode)following=false;}}/>{/key}</div></section>
{:else if step.type==='pending'}{@const part=step.part??0}{@const title=part===0?room.settings.redRegion:part===1?room.settings.redProducer:room.settings.redGrape}{@const text=part===0?room.settings.redRegionText:part===1?room.settings.redProducerText:room.settings.redGrapeText}<section class="story-card"><div class="story-visual"><ArticleThumb kind="skins" slug="rotwein"/><span class="pill">{t('m_6f558adbe2')} {step.label.toUpperCase()}</span></div><div class="story-content"><div class="eyebrow">{room.settings.redName||'DAS ROTE FINALE'}</div><h2>{title||(part===0?'Woher kommt unser Rotwein?':part===1?'Wer macht ihn?':'Welche Traube steckt drin?')}</h2><div class="prose">{#if text}{#each text.split('\n').filter(Boolean) as p}<p>{p}</p>{/each}{:else}<p>{t('m_0c3bb33635')} {part===0?'Die Region':part===1?'Den Betrieb':'Die Rebsorte'} {t('m_b04ae9e019')}</p><p>{t('m_0c6472e819')}</p>{/if}</div>{#if hostMode}<button class="button outline" style="margin-top:20px" onclick={()=>settingsOpen=true}>{t('m_b700e829ba')}<Icon name="plus" size={16}/></button>{/if}</div></section>{#if hostMode&&room.settings.redStory}<section class="host-extras"><h3><Icon name="sound" size={18}/>{t('m_2496218594')}</h3>{#each room.settings.redStory.split('\n').filter(Boolean) as p}<p>{p}</p>{/each}</section>{/if}
{:else if article}<section class="story-card">{#if article.image}<div class="story-visual"><img class='editorial-image' style={'--image-position:'+(article.imagePosition||'center')+';--image-position-mobile:'+(article.imagePositionMobile||article.imagePosition||'center')+';--image-fit:'+(article.imageFit||'cover')} src={imageSrc(article.image)} alt={article.imageAlt||(article.image==='saar-illustration'?'Illustration eines Schiefer-Flusstals':article.category==='Regionen'?'Weinberge in '+article.title:'Illustration zum Thema '+article.title)}/><span class="pill">{step.type==='break'?'KLEINE WEINPAUSE':step.label.toUpperCase()}</span><span class="image-credit">{creditFor(article).text}</span></div>{/if}<div class="story-content">{#if !article.image}<span class="chapter-label">{step.type==='break'?'Weinwissen zwischendurch':step.label}</span>{/if}<div class="eyebrow">{article.eyebrow.toUpperCase()}</div><h2>{article.title}<span class="accent">.</span></h2><p class="lead">{article.intro}</p><ArticleBody {article} compact/><div class="fact-box"><Icon name="sparkles" size={18}/><div><small>{t('m_9b729ef16b')}</small>{article.fact}</div></div></div></section>{#if hostMode}<section class="host-extras"><h3><Icon name="sound" size={18}/>{t('m_2496218594')}</h3><p class="small" style="margin-top:7px">{t('m_b0f559e7f3')}</p>{#each article.host as p}<p>{p}</p>{/each}</section>{/if}{/if}
</div>{/key}</div><aside class="tasting-aside"><div class="current-wine"><div class="eyebrow">{step.type==='finish'?'DIE WEINE':'GERADE IM GLAS · 0'+(step.wine+1)}</div><WineBottle {wine} credit interactive/><h3>{currentName}</h3><p>{step.wine===3&&room.settings.redProducer?room.settings.redProducer:wine.producer}</p><p>{step.wine===3?room.settings.redRegion||'Herkunft noch offen':wine.region}{room.settings.vintages?.[step.wine]?' · '+room.settings.vintages[step.wine]:''}</p><span class="wine-style">{wine.style}</span><button class="text-button" onclick={()=>notes(step.wine)}>{t('m_85eb8718cf')}<Icon name="notes" size={16}/></button></div>{#if !hostMode}<div class="follow-card"><div><Icon name={following?'live':'pause'} size={17}/>{following?'Du folgst dem Host.':'Du blätterst selbst.'}</div><p>{following?'Wenn der Host weitergeht, gehst du automatisch mit. Du kannst jederzeit selbst zurückblättern.':'Lies vor oder zurück. Deine Notizen bleiben dabei an ihrem Platz.'}</p>{#if !following}<button class="button outline" onclick={follow}>{t('m_1d00e87255')}<Icon name="right" size={15}/></button>{/if}</div>{/if}<div class="chapter-list"><small>{t('m_bbb0b403e3')}</small>{#each wineSteps as s}<button class:active={index===s.index} onclick={()=>move(s.index)}><span class="chapter-dot"></span>{s.label}</button>{/each}</div></aside></div>
</div><div class="tasting-controls"><div class="progress-info" role="status" aria-live="polite" aria-atomic="true"><div class="progress-bar"><span style={'width:'+((index+1)/steps.length*100)+'%'}></span></div><span>{String(index+1).padStart(2,'0')} / {steps.length}</span><span class="step-label">{step.label}</span></div>{#if !hostMode}<button class="button outline host-follow" onclick={following?()=>notes(step.wine):follow}><Icon name={following?'notes':'live'} size={15}/>{following?'Notizen':'Zum Host'}</button>{/if}<button class="button outline prev-control" disabled={index===0||busy} onclick={()=>move(index-1)} aria-label={t('m_476f19dd54')}><Icon name="left" size={17}/><span>{t('m_4080624342')}</span></button><button class="button primary" disabled={index===steps.length-1||busy} onclick={()=>move(index+1)}>{busy?'…':hostMode?'Für alle weiter':'Weiter'}<Icon name="right" size={17}/></button></div>
{/if}
<Modal bind:open={qrOpen} title={t('m_cb17e17fc4')}><div class="qr-block">{#if qr}<img src={qr} alt={'QR-Code zum Tasting '+code}/>{/if}<span class="code-input">{code}</span><p>{t('m_b7c4ae7df5')}</p><input value={joinUrl} readonly aria-label={t('m_bcea602b60')} onclick={(e)=>e.currentTarget.select()}/><button class="button primary full" onclick={copy}><Icon name={copied?'check':'copy'} size={16}/>{copied?'Link kopiert':'Teilnahmelink kopieren'}</button><p style="margin-top:12px">{t('m_72a7afeab1')}</p></div></Modal>
<Modal bind:open={membersOpen} title={t('m_cbba38ab74')}><p class="muted">{members.length} {members.length===1?'Person ist':'Personen sind'} {t('m_049a9c1ce8')}</p><div class="members-list">{#each members as m}<span><Icon name="users" size={14}/>{m.name}</span>{/each}</div></Modal>
<Modal bind:open={settingsOpen} title={t('m_b38ae339ee')}><form class="host-settings" onsubmit={(e)=>{e.preventDefault();saveSettings();}}><p>{t('m_2fa048f8be')}</p><h3>{t('m_0afb0751d8')}</h3><div class="form-grid">{#each wines as w,i}<label>{i===3?'Rotwein':w.name}<input bind:value={settings.vintages[i]} maxlength="20" placeholder={t('m_2922341d00')}/></label>{/each}</div><label>{t('m_7b922bf521')}<input bind:value={settings.rieslingLabel} maxlength="160" placeholder={t('m_a4ee5f69bd')}/></label><h3>{t('m_fb58d37d35')}</h3><label>{t('m_709a23220f')}<input bind:value={settings.redName} maxlength="120" placeholder={t('m_7c6d368728')}/></label><label>{t('m_684370b607')}<input bind:value={settings.redProducer} maxlength="120"/></label><div class="form-grid"><label>{t('m_0f21717994')}<input bind:value={settings.redRegion} maxlength="120"/></label><label>{t('m_65b33b1fe8')}<input bind:value={settings.redGrape} maxlength="120"/></label></div><label>{t('m_8276ffdfdc')}<textarea rows="4" bind:value={settings.redRegionText} maxlength="6000"></textarea></label><label>{t('m_875b4cebdd')}<textarea rows="4" bind:value={settings.redProducerText} maxlength="6000"></textarea></label><label>{t('m_4591677467')}<textarea rows="4" bind:value={settings.redGrapeText} maxlength="6000"></textarea></label><label>{t('m_a8ae1387f6')}<textarea rows="6" bind:value={settings.redStory} maxlength="8000" placeholder={t('m_9a82de5c8a')}></textarea></label>{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="button primary full" disabled={settingsBusy}>{settingsBusy?'Wird gespeichert …':'Für das Tasting speichern'}<Icon name="check" size={16}/></button></form></Modal>
<Modal bind:open={finishOpen} title={t('m_bca14c2a6c')}><p class="muted">{t('m_49ca8ea053')}</p><button class="button primary full" disabled={busy} onclick={finish}>{t('m_50671cc6df')}</button></Modal>
